const CardItem_Map = (mapx,mapy,mlevel) => {

    let map: naver.maps.Map;
   let mapOption = {
      center: new naver.maps.LatLng(mapy,mapx),
      zoom: mlevel
   };

   if(!map){
    map = new naver.maps.Map("map", mapOption);
   }

    return (
        <div className="cardItemMap" id="map">
            
        </div>
    );
}


export default CardItem_Map;
